using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;using DeliveryRider;using Newtonsoft.Json.Linq;
public static class MyeongjiStreetDetails {
 const string Folder="Assets/_Game/Art/Myeongji/StreetDetails";
 static GameObject Map=>SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="MyeongjiMap");
 static GameObject Root(string name){var old=Map.transform.Find(name);if(old!=null)throw new Exception(name+" already exists");var g=new GameObject(name);g.transform.SetParent(Map.transform,true);return g;}
 static void Guard(){var s=SceneManager.GetActiveScene();if(EditorApplication.isPlaying||s.isDirty||!s.path.EndsWith("FourDistrictPrototype_Myeongji.unity"))throw new Exception("Saved map edit scene required");if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder("Assets/_Game/Art/Myeongji","StreetDetails");}
 static Material[] Palette(){var all=Map.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Where(m=>m!=null).ToArray();Material Find(string suffix)=>all.First(m=>m.name==suffix);Material Green(string name,string hex){string p=Folder+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(m!=null)return m;m=new Material(Find("KIT_DistrictWall_A9B5A1")){name=name};ColorUtility.TryParseHtmlString(hex,out var c);m.SetColor("_BaseColor",c);m.SetFloat("_Smoothness",.05f);AssetDatabase.CreateAsset(m,p);return m;}
 return new[]{Find("KIT_DistrictWall_B3816D"),Find("KIT_DistrictWall_DDD8C9"),Find("KIT_DistrictRoof_747E80"),Green("Foliage_MutedGreen","#687F5C"),Green("Foliage_Sage","#8A9B70"),Find("KIT_DistrictWall_8FA6B0")};}
 class Build {public List<Vector3> v=new List<Vector3>();public List<int>[] ids=Enumerable.Range(0,6).Select(_=>new List<int>()).ToArray();public void Tri(Vector3 a,Vector3 b,Vector3 c,int m){int n=v.Count;v.AddRange(new[]{a,b,c});ids[m].AddRange(new[]{n,n+1,n+2});}public void Q(Vector3 a,Vector3 b,Vector3 c,Vector3 d,int m,Vector3 n){if(Vector3.Dot(Vector3.Cross(b-a,c-a),n)<0){Tri(a,c,b,m);Tri(a,d,c,m);}else{Tri(a,b,c,m);Tri(a,c,d,m);}}
 public void Box(Vector3 center,Vector3 size,int m){var e=size*.5f;var a=center+new Vector3(-e.x,-e.y,-e.z);var b=center+new Vector3(e.x,-e.y,-e.z);var c=center+new Vector3(e.x,e.y,-e.z);var d=center+new Vector3(-e.x,e.y,-e.z);var E=a+Vector3.forward*size.z;var F=b+Vector3.forward*size.z;var G=c+Vector3.forward*size.z;var H=d+Vector3.forward*size.z;Q(E,F,G,H,m,Vector3.forward);Q(b,a,d,c,m,Vector3.back);Q(a,E,H,d,m,Vector3.left);Q(F,b,c,G,m,Vector3.right);Q(d,H,G,c,m,Vector3.up);Q(a,b,F,E,m,Vector3.down);}
 public void Ring(Vector3 center,float y0,float y1,float r0,float r1,int m,int sides=8){for(int i=0;i<sides;i++){float a=i*2*Mathf.PI/sides,z=(i+1)*2*Mathf.PI/sides;var x=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));var w=new Vector3(Mathf.Cos(z),0,Mathf.Sin(z));var A=center+x*r0+Vector3.up*y0;var B=center+w*r0+Vector3.up*y0;var C=center+w*r1+Vector3.up*y1;var D=center+x*r1+Vector3.up*y1;Q(A,B,C,D,m,x+w);Tri(center+Vector3.up*y1,D,C,m);Tri(center+Vector3.up*y0,B,A,m);}}
 public void Crown(Vector3 c,Vector3 size,int m){ // Low-poly faceted crown with a broad middle and tapered ends.
 for(int i=0;i<7;i++){float a=i*2*Mathf.PI/7,z=(i+1)*2*Mathf.PI/7;var p=c+new Vector3(Mathf.Cos(a)*size.x,0,Mathf.Sin(a)*size.z);var q=c+new Vector3(Mathf.Cos(z)*size.x,0,Mathf.Sin(z)*size.z);var top=c+new Vector3(.12f,size.y,0);var low=c+new Vector3(-.1f,-size.y*.7f,0);Tri(p,top,q,m);Tri(q,low,p,m);}}
 public Mesh Save(string name){string path=Folder+"/"+name+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing!=null)return existing;var mesh=new Mesh{name=name};mesh.SetVertices(v);mesh.subMeshCount=6;for(int i=0;i<6;i++)mesh.SetTriangles(ids[i],i);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}}
 static Mesh Prop(string type){var b=new Build();if(type=="Planter"){b.Ring(Vector3.zero,0,.45f,.20f,.29f,0);b.Ring(Vector3.zero,.45f,.50f,.31f,.31f,0);b.Ring(Vector3.zero,.501f,.51f,.25f,.25f,2);b.Crown(new Vector3(0,.77f,0),new Vector3(.33f,.38f,.30f),3);b.Crown(new Vector3(.16f,.64f,.07f),new Vector3(.21f,.22f,.22f),4);}else if(type=="AirUnit"){b.Box(new Vector3(0,.38f,0),new Vector3(.78f,.58f,.32f),1);b.Box(new Vector3(-.22f,.055f,0),new Vector3(.10f,.11f,.29f),2);b.Box(new Vector3(.22f,.055f,0),new Vector3(.10f,.11f,.29f),2);for(int i=0;i<5;i++)b.Box(new Vector3(.06f,.21f+i*.075f,.169f),new Vector3(.51f,.022f,.018f),2);}else if(type=="Mailbox"){b.Box(new Vector3(0,.23f,0),new Vector3(.36f,.46f,.14f),5);b.Box(new Vector3(0,.35f,.078f),new Vector3(.25f,.023f,.016f),2);b.Box(new Vector3(.10f,.18f,.083f),new Vector3(.025f,.04f,.025f),1);}else{b.Box(new Vector3(0,.35f,0),new Vector3(.44f,.70f,.42f),5);b.Box(new Vector3(0,.74f,0),new Vector3(.48f,.08f,.46f),2);b.Box(new Vector3(0,.77f,.231f),new Vector3(.19f,.045f,.018f),1);}return b.Save("Prop_"+type);}
 static Mesh Tree(bool bush){var b=new Build();if(bush){b.Box(new Vector3(0,.12f,0),new Vector3(1.25f,.24f,.85f),1);b.Crown(new Vector3(-.30f,.49f,0),new Vector3(.40f,.32f,.33f),3);b.Crown(new Vector3(.27f,.53f,0),new Vector3(.44f,.38f,.34f),4);}else{b.Ring(Vector3.zero,0,.16f,.58f,.58f,1);b.Ring(Vector3.zero,.161f,.18f,.48f,.48f,2);b.Ring(Vector3.zero,.18f,3.3f,.14f,.09f,0,6);b.Crown(new Vector3(0,3.85f,0),new Vector3(1.10f,1.15f,1.02f),3);b.Crown(new Vector3(.53f,3.60f,.1f),new Vector3(.72f,.83f,.76f),4);}return b.Save(bush?"Greenery_ShrubBed":"Greenery_Tree");}
 static PedestrianNetwork Net=>SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="Pedestrians").GetComponent<PedestrianNetwork>();
 static float Distance(Vector3 p,Vector3 a,Vector3 b){p.y=a.y=b.y=0;var d=b-a;return Vector3.Distance(p,a+d*Mathf.Clamp01(Vector3.Dot(p-a,d)/Mathf.Max(.0001f,d.sqrMagnitude)));}
 static bool PathClear(Vector3 p,float radius){var net=Net;for(int i=0;i<net.PathCount;i++){var path=net.Path(i);for(int j=1;j<path.points.Length;j++)if(Distance(p,path.points[j-1],path.points[j])<path.halfWidth+radius+.12f)return false;}foreach(var a in JArray.Parse(File.ReadAllText("Docs/MapLayout/Myeongji/anchors.json"))){var pos=new Vector3((float)a["position"][0],0,(float)a["position"][2]);if(Vector3.Distance(new Vector3(p.x,0,p.z),pos)<radius+1.15f)return false;}return true;}
 static bool Surface(Vector3 p,float radius,bool plotOnly){var col=Map.transform.Find("Ground").GetComponentInChildren<MeshCollider>();var materials=col.GetComponent<Renderer>().sharedMaterials;for(int i=0;i<5;i++){var q=p+(i==0?Vector3.zero:new Vector3(i%2==0?radius:-radius,0,i<3?radius:-radius));if(!col.Raycast(new Ray(q+Vector3.up*20,Vector3.down),out var hit,40)||Mathf.Abs(hit.point.y)>.04f)return false;int t=hit.triangleIndex,sub=0;while(t>=col.sharedMesh.GetIndexCount(sub)/3){t-=(int)col.sharedMesh.GetIndexCount(sub)/3;sub++;}var name=materials[sub].name;if(plotOnly?name!="ST_Plot":name!="ST_Plot"&&name!="ST_Pavement")return false;}return true;}
 static GameObject Place(Transform parent,string name,Mesh mesh,Material[] mats,Vector3 position,Quaternion rotation,Vector3 colliderCenter,Vector3 colliderSize){var g=new GameObject(name);g.transform.SetPositionAndRotation(position,rotation);g.transform.SetParent(parent,true);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterials=mats;var col=g.AddComponent<BoxCollider>();col.center=colliderCenter;col.size=colliderSize;Physics.SyncTransforms();return g;}
 static bool Occupied(Vector3 p,Vector3 size,Quaternion rot){return Physics.OverlapBox(p,size*.5f,rot,~0,QueryTriggerInteraction.Ignore).Any(c=>c.transform!=Map.transform.Find("Ground")&&c.name!="Ground");}
 public static string Props(){Guard();var root=Root("EntranceDetails");var mats=Palette();var lots=(JArray)JObject.Parse(File.ReadAllText("Docs/MapLayout/Myeongji/layout.json"))["lots"];int count=0,skipped=0,index=0;foreach(var lot in lots){string id=(string)lot[0];int current=index++;if(current%4==3)continue;var r=Map.GetComponentsInChildren<MeshRenderer>().Single(v=>v.name=="AB01_"+id+".001");var col=r.GetComponent<MeshCollider>();int rot=(int)lot[7];var n=rot==0?Vector3.back:rot==180?Vector3.forward:rot==90?Vector3.right:Vector3.left;var u=Mathf.Abs(n.z)>.5f?Vector3.right:Vector3.forward;float lo=Vector3.Dot(r.bounds.center,u)-Mathf.Abs(Vector3.Dot(r.bounds.extents,u)),hi=Vector3.Dot(r.bounds.center,u)+Mathf.Abs(Vector3.Dot(r.bounds.extents,u));float edge=Vector3.Dot(r.bounds.center,n)+Mathf.Abs(Vector3.Dot(r.bounds.extents,n));string type=new[]{"Planter","Mailbox","AirUnit","Bin"}[current%4];var mesh=Prop(type);var size=mesh.bounds.size;bool placed=false;foreach(float x in new[]{lo+.68f,hi-.68f,lo+1.15f,hi-1.15f}){var start=u*x+n*(edge+2)+Vector3.up*(type=="Mailbox"?1.35f:.45f);if(!col.Raycast(new Ray(start,-n),out var hit,5))continue;var p=new Vector3(hit.point.x,0,hit.point.z)+n*(size.z/2+.06f);float radius=Mathf.Sqrt(size.x*size.x+size.z*size.z)/2;if(!PathClear(p,radius)||!Surface(p,Mathf.Min(radius,.28f),false))continue;if(type=="Mailbox")p.y=1.10f;var rotation=Quaternion.LookRotation(n);if(Occupied(p+Vector3.up*mesh.bounds.center.y,size,rotation))continue;Place(root.transform,id+"_"+type,mesh,mats,p,rotation,mesh.bounds.center,mesh.bounds.size);placed=true;count++;break;}if(!placed)skipped++;}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return "Entrance props "+count+", tight locations skipped "+skipped;}
 public static string Greenery(){Guard();var root=Root("StreetGreenery");var mats=Palette();var tree=Tree(false);var bush=Tree(true);var buildings=Map.GetComponentsInChildren<Renderer>().Where(r=>r.name.StartsWith("AB01_")).ToArray();var candidates=new List<Vector3>();for(float x=7;x<=111;x+=3.3f)for(float z=-94;z<=-10;z+=3.1f){var p=new Vector3(x,0,z);if(!PathClear(p,.80f)||!Surface(p,.70f,true))continue;float near=float.MaxValue;for(int i=0;i<Net.PathCount;i++){var path=Net.Path(i);for(int j=1;j<path.points.Length;j++)near=Mathf.Min(near,Distance(p,path.points[j-1],path.points[j]));}if(near>6||near<2.2f)continue;candidates.Add(p);}var placed=new List<Vector3>();int trees=0,bushes=0;foreach(var p in candidates.OrderBy(p=>Mathf.Repeat(p.x*13.37f+p.z*7.19f,97))){bool isTree=trees<14;float spacing=isTree?10:5;if(placed.Any(q=>Vector3.Distance(p,q)<spacing))continue;var check=new Bounds(p+Vector3.up*(isTree?2.6f:.5f),isTree?new Vector3(2.8f,5.2f,2.8f):new Vector3(1.4f,1.1f,1.05f));if(buildings.Any(r=>r.bounds.Intersects(check))||Occupied(check.center,check.size,Quaternion.identity))continue;var mesh=isTree?tree:bush;Place(root.transform,(isTree?"Tree_":"ShrubBed_")+(isTree?trees:bushes).ToString("00"),mesh,mats,p,Quaternion.identity,isTree?new Vector3(0,1.5f,0):mesh.bounds.center,isTree?new Vector3(1.16f,3,1.16f):mesh.bounds.size);placed.Add(p);if(isTree)trees++;else bushes++;if(trees>=14&&bushes>=14)break;}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return "Trees "+trees+", shrub beds "+bushes;} public static string Shrubs(){Guard();var root=Map.transform.Find("StreetGreenery").gameObject;var mats=Palette();var tree=Tree(false);var bush=Tree(true);var buildings=Map.GetComponentsInChildren<Renderer>().Where(r=>r.name.StartsWith("AB01_")).ToArray();var candidates=new List<Vector3>();for(float x=7;x<=111;x+=3.3f)for(float z=-94;z<=-10;z+=3.1f){var p=new Vector3(x,0,z);if(!PathClear(p,.80f)||!Surface(p,.70f,true))continue;float near=float.MaxValue;for(int i=0;i<Net.PathCount;i++){var path=Net.Path(i);for(int j=1;j<path.points.Length;j++)near=Mathf.Min(near,Distance(p,path.points[j-1],path.points[j]));}if(near>6||near<2.2f)continue;candidates.Add(p);}var placed=root.transform.Cast<Transform>().Select(t=>t.position).ToList();int trees=14,bushes=0;foreach(var p in candidates.OrderBy(p=>Mathf.Repeat(p.x*13.37f+p.z*7.19f,97))){bool isTree=trees<14;float spacing=isTree?10:5;if(placed.Any(q=>Vector3.Distance(p,q)<spacing))continue;var check=new Bounds(p+Vector3.up*(isTree?2.6f:.5f),isTree?new Vector3(2.8f,5.2f,2.8f):new Vector3(1.4f,1.1f,1.05f));if(buildings.Any(r=>r.bounds.Intersects(check))||Occupied(check.center,check.size,Quaternion.identity))continue;var mesh=isTree?tree:bush;Place(root.transform,(isTree?"Tree_":"ShrubBed_")+(isTree?trees:bushes).ToString("00"),mesh,mats,p,Quaternion.identity,isTree?new Vector3(0,1.5f,0):mesh.bounds.center,isTree?new Vector3(1.16f,3,1.16f):mesh.bounds.size);placed.Add(p);if(isTree)trees++;else bushes++;if(trees>=14&&bushes>=14)break;}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return "Additional shrub beds "+bushes;}
 public static string SideProps(){Guard();var root=Map.transform.Find("EntranceDetails");var mats=Palette();var lots=(JArray)JObject.Parse(File.ReadAllText("Docs/MapLayout/Myeongji/layout.json"))["lots"];int count=0;var counts=new Dictionary<string,int>();foreach(var lot in lots){if(count>=24)break;string id=(string)lot[0];if(root.Find(id+"_SideProp")!=null)continue;string type=new[]{"Planter","AirUnit","Bin"}[count%3];var mesh=Prop(type);var size=mesh.bounds.size;var r=Map.GetComponentsInChildren<MeshRenderer>().Single(v=>v.name=="AB01_"+id+".001");var building=r.GetComponent<MeshCollider>();int rot=(int)lot[7];var front=rot==0?Vector3.back:rot==180?Vector3.forward:rot==90?Vector3.right:Vector3.left;var side=Mathf.Abs(front.z)>.5f?Vector3.right:Vector3.forward;float edge=Vector3.Dot(r.bounds.center,front)+Mathf.Abs(Vector3.Dot(r.bounds.extents,front));bool placed=false;foreach(float sign in new[]{1f,-1f}){if(placed)break;var n=side*sign;float sideEdge=Vector3.Dot(r.bounds.center,n)+Mathf.Abs(Vector3.Dot(r.bounds.extents,n));foreach(float inset in new[]{.9f,1.7f,2.6f}){var start=front*(edge-inset)+n*(sideEdge+2)+Vector3.up*.45f;if(!building.Raycast(new Ray(start,-n),out var hit,4))continue;var pos=new Vector3(hit.point.x,0,hit.point.z)+n*(size.z/2+.06f);float radius=Mathf.Sqrt(size.x*size.x+size.z*size.z)/2;if(!PathClear(pos,radius)||!Surface(pos,Mathf.Min(radius,.3f),false))continue;var q=Quaternion.LookRotation(n);if(Occupied(pos+Vector3.up*mesh.bounds.center.y,size,q))continue;var g=Place(root,id+"_SideProp",mesh,mats,pos,q,mesh.bounds.center,mesh.bounds.size);g.name=id+"_"+type+"_SideProp";count++;if(!counts.ContainsKey(type))counts[type]=0;counts[type]++;placed=true;break;}}}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return string.Join(", ",counts.Select(p=>p.Key+" "+p.Value));}

